exercises.solution:
def f_rec(n):
    if n < 3:
        return n
    return f_rec(n - 1) + 2 * f_rec(n - 2) + 3 * f_rec(n - 3)


def f_iter(n):
    if n < 3:
        return n
    a, b, c = 0, 1, 2
    for k in range(3, n + 1):
        next_value = c + 2 * b + 3 * a
        a, b, c = b, c, next_value
    return c
